SELECT * FROM message
WHERE receiver_id IS NULL AND deleted_at IS NULL

    AND id < #{cursor}

ORDER BY id DESC
LIMIT #{size}

SELECT * FROM message
WHERE deleted_at IS NULL
AND (
    (sender_id = #{userId} AND receiver_name = #{targetName})
    OR (sender_id = #{targetUserId} AND receiver_name = #{senderName})
)

    AND id < #{cursor}

ORDER BY id DESC
LIMIT #{size}
